<script setup>
import {onMounted,onBeforeUnmount} from 'vue'
import {storyOpen,storyOrigin,stories,closeStory} from './designStories'
function key(e){if(e.key==='Escape'&&storyOpen.value)closeStory();if(e.key==='Tab'&&storyOpen.value){const a=[...document.querySelectorAll('.design-dialog button,.design-dialog a')];if(e.shiftKey&&document.activeElement===a[0]){e.preventDefault();a.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===a.at(-1)){e.preventDefault();a[0]?.focus()}}}
onMounted(()=>document.addEventListener('keydown',key));onBeforeUnmount(()=>document.removeEventListener('keydown',key))
</script>
<template><Teleport to="body"><Transition name="design"><div v-if="storyOpen" class="design-overlay" @click.self="closeStory" :style="{'--origin':storyOrigin}"><section class="design-dialog" role="dialog" aria-modal="true" aria-labelledby="design-title"><button class="design-close" @click="closeStory" aria-label="关闭项目设计">✕</button><div class="design-scroll"><div class="design-hero"><img :src="storyOpen.cover" alt=""><div><span>BEHIND THE GAME / 设计与制作</span><h2 id="design-title">{{stories[storyOpen.visual].name}}</h2><p>{{stories[storyOpen.visual].sub}}</p></div></div><div class="design-body"><article v-for="([title,text],i) in stories[storyOpen.visual].sections" :key="title" :style="{'--i':i}"><span class="design-number">0{{i+1}}</span><div><h3>{{title}}</h3><p>{{text}}</p></div></article><a :href="storyOpen.playUrl||storyOpen.videoUrl" target="_blank" rel="noopener noreferrer" class="design-action">▶ {{storyOpen.playUrl?'在线试玩':'观看实机视频'}} ↗</a><a v-if="storyOpen.sourceUrl" :href="storyOpen.sourceUrl" target="_blank" rel="noopener noreferrer" class="design-action design-source">查看开源项目 ↗</a></div></div></section></div></Transition></Teleport></template>
<style>
.design-entry{border:1px solid #ac8ac7;border-radius:99px;background:linear-gradient(120deg,#ffffffb0,#e8daf3);color:#66457d;padding:10px 18px;font:inherit;font-weight:600;cursor:pointer;transition:box-shadow .25s,transform .25s}.design-entry:hover{box-shadow:0 0 24px #ad79dc65;transform:translateY(-2px)}
.design-overlay{position:fixed;inset:0;z-index:10000;background:#1d1129b8;backdrop-filter:blur(12px);display:grid;place-items:center;padding:30px;perspective:1200px}.design-dialog{position:relative;width:min(1060px,100%);height:min(880px,90dvh);border:1px solid #e2c5fc99;border-radius:26px;background:#f9f6fb;box-shadow:0 0 80px #b18cda40,0 40px 100px #14091c80;overflow:hidden;transform-origin:var(--origin,50% 55%)}.design-close{position:absolute;right:18px;top:18px;z-index:3;width:42px;height:42px;border-radius:50%;background:#fffdf5;border:1px solid #cdb6df;color:#513063;font-size:21px;cursor:pointer}.design-scroll{height:100%;overflow:auto;overscroll-behavior:contain}.design-hero{height:290px;position:relative;color:white;overflow:hidden}.design-hero img{width:100%;height:100%;object-fit:cover}.design-hero:after{content:'';position:absolute;inset:0;background:linear-gradient(transparent,#251332e8)}.design-hero>div{position:absolute;z-index:1;bottom:25px;left:45px;right:55px}.design-hero span{font-size:10px;letter-spacing:3px}.design-hero h2{font-size:38px;margin:10px 0}.design-hero p{margin:0;color:#f0e5f7}.design-body{padding:25px 45px 45px}.design-body article{display:grid;grid-template-columns:45px 1fr;gap:15px;padding:24px 0;border-bottom:1px solid #b99eca35;animation:story-reveal .65s both;animation-delay:calc(100ms + var(--i)*65ms)}.design-number{font-size:12px;color:#a177bd;padding-top:7px}.design-body h3{font-size:21px;color:#513762;margin:0 0 13px}.design-body p{white-space:pre-line;line-height:1.95;color:#62516d;font-size:15px;margin:0}.design-action{display:inline-block;margin:28px 0 0 60px;padding:13px 24px;background:#77518e;color:white;border-radius:99px;text-decoration:none}.design-enter-active{transition:opacity .45s}.design-leave-active{transition:opacity .3s}.design-enter-active .design-dialog{animation:story-open .7s cubic-bezier(.16,1,.3,1)}.design-leave-active .design-dialog{transition:transform .3s,opacity .3s}.design-enter-from,.design-leave-to{opacity:0}.design-leave-to .design-dialog{transform:scale(.82) translateY(20px)}@keyframes story-open{0%{opacity:0;transform:translateY(60px) rotateX(9deg) scale(.83);filter:blur(8px);box-shadow:0 0 130px #c394ff}100%{opacity:1;transform:none;filter:blur(0)}}@keyframes story-reveal{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:none}}@media(max-width:650px){.design-overlay{padding:12px}.design-dialog{height:94dvh;border-radius:18px}.design-hero{height:240px}.design-hero>div{left:22px}.design-hero h2{font-size:30px}.design-body{padding:10px 22px 30px}.design-body article{grid-template-columns:25px 1fr;gap:8px}.design-body p{font-size:14px}.design-action{margin-left:33px}}@media(prefers-reduced-motion:reduce){.design-overlay *{animation:none!important;transition:none!important}}
</style>
